  ('1489d3d0-784d-b722-b513-dd445a8f7e35','00000000-0000-0000-0000-000000000018','Contract Scroll — First Born Child','Vellum, signed in blood','Books & Manuscripts','Legal Documents',NULL,'The original deal. First of thousands. All legally binding.',2200000,0,true,'COLLECTION',1780139324259,false),
  ('3cad0523-97d7-9f0e-b5c4-bf66251391e6','00000000-0000-0000-0000-000000000018','Midas','Gold-plated leather, cursed','Historical Artifacts','Curiosities',NULL,'Everything it touches turns to gold. Handle with extreme care.',9800000,0,true,'COLLECTION',1780142924259,false),
  ('991dd723-0d9a-a435-8573-2a134ce0cd8d','00000000-0000-0000-0000-000000000018','True Name Ledger','Bound in human skin, iron clasp','Books & Manuscripts','Grimoires',NULL,'Every name in here can be commanded. 3,000 entries.',5600000,0,true,'COLLECTION',1780146524259,false),
  ('5305440b-3746-21d6-3d59-03e3202bbba8','00000000-0000-0000-0000-000000000018','Cinderella','Silica crystal, fitted for one foot only','Historical Artifacts','Curiosities',NULL,'Acquired in exchange for a pumpkin carriage and driver.',1200000,0,true,'COLLECTION',1780150124259,false),
  ('a0c60239-21a9-7849-a831-161054e55bf2','00000000-0000-0000-0000-000000000018','Sleeping Beauty','Enchanted iron, drop spindle','Historical Artifacts','Curiosities',NULL,'One prick causes century-long sleep. Still active.',3400000,0,true,'COLLECTION',1780153724259,false),
  ('88b38f4c-3fcb-5524-fb4e-2b859e96bcbb','00000000-0000-0000-0000-000000000018','Magic Mirror — Snow White','Obsidian glass, gold frame','Historical Artifacts','Curiosities',NULL,'Knows who is fairest. Compulsively honest. Deeply unhappy.',2800000,0,true,'COLLECTION',1780157324259,false),
  ('dffd3716-6268-7741-31ef-6d74c8a02fa3','00000000-0000-0000-0000-000000000018','Jack','Dried legumes, extraordinary properties','Historical Artifacts','Curiosities',NULL,'Each grows a beanstalk to a different giant',480000,0,true,'COLLECTION',1780160924259,false),
  ('401e3112-3658-cf52-142f-53c74c96ddcd','00000000-0000-0000-0000-000000000018','Pinocchio','Pine wood, grows when lying','Historical Artifacts','Curiosities',NULL,'Shaving from Geppetto',280000,0,true,'COLLECTION',1780164524259,false),
  ('ab9ccb0f-f130-9d24-f6ef-2d79b0c9dec8','00000000-0000-0000-0000-000000000018','Poison Apple — Preserved','Enchanted fruit, Snow White variety','Historical Artifacts','Curiosities',NULL,'Half-eaten. The other half is still in Snow White',1800000,0,true,'COLLECTION',1780168124259,false),
  ('9b31765c-bd61-e17b-72aa-0e771f651951','00000000-0000-0000-0000-000000000018','Lamp — Djinn Vessel','Brass oil lamp, Arabian origin','Historical Artifacts','Curiosities',NULL,'Three wishes remaining. Previous owner used two poorly.',8400000,0,true,'COLLECTION',1780171724259,false),
  ('bf9542bd-db9b-346a-3d99-e49298303cbd','00000000-0000-0000-0000-000000000018','Beanstalk Giant','Iron, sized for a 40-foot being','Historical Artifacts','Jewelry',NULL,'Fee-fi-fo-fum. Acquired from Jack in a secondary deal.',380000,0,true,'COLLECTION',1780175324259,false),
  ('66dbb379-c60c-3391-6702-4953089e5835','00000000-0000-0000-0000-000000000018','Rumpelstiltskin','Issued by the Fairy Court, witnessed','Books & Manuscripts','Legal Documents',NULL,'If anyone reads this aloud, the deal is nullified. SEALED.',6200000,0,true,'COLLECTION',1780178924259,false),
  ('86663b02-8af1-3f49-722b-1b9b9e1e332f','00000000-0000-0000-0000-000000000018','Pied Piper','Bone pipe, enchanted melody','Music & Instruments','Ancient Instruments',NULL,'Leads rats — and children. Acquired after Hamelin dispute.',2200000,0,true,'COLLECTION',1780182524259,false),
  ('7e1a7510-74d1-67b4-6a04-0133ea118c35','00000000-0000-0000-0000-000000000018','Red Riding Hood','Scarlet wool, wolf-repelling enchantment','Historical Artifacts','Curiosities',NULL,'Actually repels wolves. Grandmother had better wool.',280000,0,true,'COLLECTION',1780186124259,false),
  ('ab7194a3-85a4-9ca2-3bdc-b31304329815','00000000-0000-0000-0000-000000000018','Frog Prince Lily Pad Collection','Preserved enchanted amphibian habitat','Natural History','Curiosities',NULL,'Seventeen princes mid-transformation. Stored for leverage.',680000,0,true,'COLLECTION',1780189724259,false),
  ('5ba5dc16-7819-2b8d-35da-3cb95e16432f','00000000-0000-0000-0000-000000000018','Hansel and Gretel','Petrified carbohydrates, c. fairy tale era','Historical Artifacts','Curiosities',NULL,'Birds ate the real ones. These are from the witch',45000,0,true,'COLLECTION',1780193324259,false),
  ('45f753d8-be5c-ee21-0cce-c8191e487dba','00000000-0000-0000-0000-000000000018','Witch','Iron, self-stirring, Russian tradition','Historical Artifacts','Curiosities',NULL,'Baba Yaga traded it for three questions answered.',980000,0,true,'COLLECTION',1780196924259,false),
  ('94979e58-1f32-0d55-cf41-4d1c37f86ba0','00000000-0000-0000-0000-000000000018','Cursed Gold Coins — Pieces of Eight','Aztec gold, Pirates of the Caribbean type','Coins & Currency','Ancient Coins',NULL,'Every coin must be returned or the curse holds. Still 23 missing.',1200000,0,true,'COLLECTION',1780200524259,false),
  ('f1e02916-6837-5d45-1ef2-3485ccd04c80','00000000-0000-0000-0000-000000000018','Twelve Dancing Princesses','Set of twelve pairs, worn through at sole','Historical Artifacts','Curiosities',NULL,'Worn out every night in the underground kingdom.',480000,0,true,'COLLECTION',1780204124259,false),
  ('ead4f535-38fe-3603-ea3b-a09526aa67a6','00000000-0000-0000-0000-000000000018','Seven League Boots','Leather, enchanted stride','Historical Artifacts','Curiosities',NULL,'Each step covers seven leagues. Very hard to park.',1400000,0,true,'COLLECTION',1780207724259,false),
  ('6f3b63f8-c0a3-f306-847b-3d651033e283','00000000-0000-0000-0000-000000000018','Grimm Brothers Manuscript — Fairy Tales','Jacob and Wilhelm Grimm, 1812 first edition','Books & Manuscripts','Rare Books',NULL,'His stories are in here. He finds this amusing.',285000,0,true,'COLLECTION',1780211324259,false),
  ('d2c8ce37-95eb-dc59-ba66-2923c1501621','00000000-0000-0000-0000-000000000018','Enchanted Rose — Beauty and the Beast','Glass dome, single crimson rose','Historical Artifacts','Curiosities',NULL,'Petals still falling. Prince has until the last petal.',2800000,0,true,'COLLECTION',1780214924259,false),
  ('e00d8c8c-a955-75ed-f868-55e3ea724494','00000000-0000-0000-0000-000000000018','Raven','Black feather, speaking ability','Historical Artifacts','Curiosities',NULL,'Acquired from Huginn or Muninn — neither will say which.',680000,0,true,'COLLECTION',1780218524259,false),
  ('d1c4423c-306c-bb1f-622e-6ab7d2e8f874','00000000-0000-0000-0000-000000000018','Mermaid Scale Collection','Iridescent scales, various species','Natural History','Curiosities',NULL,'Each scale grants one hour of aquatic breathing.',380000,0,true,'COLLECTION',1780222124259,false),
  ('a201e47e-9904-0a9a-9abf-2b0d490ff785','00000000-0000-0000-0000-000000000018','Pandora','Pithos vessel, ancient Greek origin','Historical Artifacts','Curiosities',NULL,'All evils of the world. Hope is still inside. DO NOT OPEN.',12000000,0,true,'COLLECTION',1780225724259,false),
  ('a0bb00f1-5e70-98cd-5856-8c0b506baa92','00000000-0000-0000-0000-000000000018','Prophecy Scroll — Unread','Oracle','Books & Manuscripts','Grimoires',NULL,'The seal breaks only when the subject reads it. Filed under ',3200000,0,true,'COLLECTION',1780229324259,false),
  ('2611c3a8-647f-def8-1b5e-d2b927ce89d7','00000000-0000-0000-0000-000000000018','Thumbelina','Miniature furniture, 2-inch scale','Historical Artifacts','Curiosities',NULL,'Tiny human girl lived in this. Traded for a pea-sized gem.',45000,0,true,'COLLECTION',1780232924259,false),
  ('8de8b6c0-e324-5459-6c94-b18bb7ddcba2','00000000-0000-0000-0000-000000000018','Troll Bridge Toll Book','Ledger of crossings and deals, c. Norse era','Books & Manuscripts','Historical Documents',NULL,'Who crossed, what they paid. Three billy goats: outstanding debt.',95000,0,true,'COLLECTION',1780236524259,false),
  ('ad8120da-c493-b896-3d04-5b3a9ec9bdda','00000000-0000-0000-0000-000000000018','Peter Pan','Detached, sewn back incorrectly','Historical Artifacts','Curiosities',NULL,'Shadow occasionally acts independently. Wendy',1800000,0,true,'COLLECTION',1780240124259,false),
  ('625400b5-9a7a-c100-0eb7-ab9733a7999b','00000000-0000-0000-0000-000000000018','Wolf','Three sealed vials: straw, stick, brick','Historical Artifacts','Curiosities',NULL,'Huffing and puffing capacity sold separately.',180000,0,true,'COLLECTION',1780243724259,false),
  ('fc841270-95e5-7d7c-5405-efff71d9fd8a','00000000-0000-0000-0000-000000000018','Ugly Duckling Feather — Swan Transformation','Pinfeather and adult swan quill','Natural History','Curiosities',NULL,'Before and after. Andersen story. Rumple witnessed it.',28000,0,true,'COLLECTION',1780247324259,false),
  ('7cf2d2a3-1a9f-b5d1-2a73-0b477e2b6a1a','00000000-0000-0000-0000-000000000018','Excalibur Scabbard Fragment','Leather and gold thread, Arthurian','Historical Artifacts','Arms & Militaria',NULL,'The scabbard prevented wounds. Rumple has a piece.',2200000,0,true,'COLLECTION',1780250924259,false),
  ('bda9fa7a-74ac-c4df-e638-e9866d5d1be9','00000000-0000-0000-0000-000000000018','Golden Goose Egg','Solid gold, still warm','Historical Artifacts','Curiosities',NULL,'Daily production stopped when farmer killed the goose. Last egg.',4200000,0,true,'COLLECTION',1780254524259,false),
  ('3032ae8a-2119-013b-ca74-8e91d7891340','00000000-0000-0000-0000-000000000018','Fairy Godmother Wand','Hazel wood and moonstone','Historical Artifacts','Curiosities',NULL,'Bibbidi-bobbidi-boo. Power fading. Needs recharging.',1600000,0,true,'COLLECTION',1780258124259,false),
  ('d361bd51-4114-42c4-54e6-60911b991688','00000000-0000-0000-0000-000000000018','Rapunzel','Golden hair, 70 feet','Historical Artifacts','Curiosities',NULL,'Cut by the witch. Still strong enough to support a prince.',380000,0,true,'COLLECTION',1780261724259,false),
  ('fe2eda8b-c4ae-56c5-1dd6-bd46a7a0832a','00000000-0000-0000-0000-000000000018','Faust','Original deal, Mephistopheles signature','Books & Manuscripts','Legal Documents',NULL,'Rumple admires the craftsmanship. He has a copy for study.',8800000,0,true,'COLLECTION',1780265324259,false),
  ('991d561c-de94-6ebe-2fdb-39c69873dd22','00000000-0000-0000-0000-000000000018','Wish-Granting Monkey','Preserved, three wishes remaining','Historical Artifacts','Curiosities',NULL,'W.W. Jacobs described it. This is the real one. Be specific.',3600000,0,true,'COLLECTION',1780268924259,false),
  ('e50f874c-5ca2-90bb-fbb1-88123216348b','00000000-0000-0000-0000-000000000018','Neverland Map','Second star to the right, hand-drawn','Books & Manuscripts','Maps',NULL,'Straight on till morning. Island moves. Map occasionally updates.',1200000,0,true,'COLLECTION',1780272524259,false),
  ('867652da-60c6-5fc3-f68e-f34f4297b80a','00000000-0000-0000-0000-000000000018','The Imp','Gold, locked in a mirror box','Historical Artifacts','Curiosities',NULL,'RUMPELSTILTSKIN. Knowing it breaks every deal. Kept hidden.',22000000,0,true,'COLLECTION',1780276124259,false)
INSERT INTO vault_items (id,profile_id,title,subtitle,universe,category,grade,notes,current_value,purchase_price,is_public,status,created_at,is_new) VALUES
  ('02258b2c-6e30-5e5a-f3dd-6e825901a06c','00000000-0000-0000-0000-000000000019','Holy Grail — Pewter Cup','Antioch Chalice style, 4th Century AD','Antiquities','Religious Artifacts',NULL,'The cup of the Last Supper. Simple. Unassuming. As it should be.',22000000,0,true,'COLLECTION',1780135724259,false),
  ('7b036ac3-135f-3045-84ac-4803911aca78','00000000-0000-0000-0000-000000000019','Ark of the Covenant — Scale Model','Reference model only. The real one is elsewhere.','Historical Artifacts','Religious Artifacts',NULL,'Full-size replica for study purposes. Real one stays where it is.',48000,18000,true,'COLLECTION',1780139324259,false),
  ('5a56c9af-331f-75a7-3d92-c275127411de','00000000-0000-0000-0000-000000000019','Sankara Stone — Third','Shiva lingam stone, Pankot Palace','Antiquities','Indian',NULL,'Recovered from the Thuggee cult. Returns heat when held.',4800000,0,true,'COLLECTION',1780142924259,false),
  ('c3e2c9b6-d456-178d-102c-2988e1582bab','00000000-0000-0000-0000-000000000019','Crystal Skull — Akator','Carved quartz crystal, Mayan style','Antiquities','Pre-Columbian',NULL,'Interdimensional origin. Heavy. Slightly uncomfortable to be near.',6200000,0,true,'COLLECTION',1780146524259,false),
  ('1ea37b76-3e28-71ad-605a-eb12c180a531','00000000-0000-0000-0000-000000000019','Spear of Destiny — Tip Fragment','Iron, Roman, 1st Century AD','Historical Artifacts','Religious Artifacts',NULL,'The lance that pierced Christ. Whoever holds it controls destiny.',9400000,0,true,'COLLECTION',1780150124259,false),
  ('77905ee2-02c8-7ee8-539f-5aba9d782644','00000000-0000-0000-0000-000000000019','Walton','Leather-bound, Morocco','Books & Manuscripts','Personal Papers',NULL,'Guatemala expedition, 1938. The map is still inside.',85000,28000,true,'COLLECTION',1780153724259,false),
  ('be3a00fd-ca38-0d05-9b89-85df152cc0dc','00000000-0000-0000-0000-000000000019','Fedora Hat — Field Grade','Herbert Johnson, London','Historical Artifacts','Clothing',NULL,'The hat. Never goes down without it.',280000,95000,true,'COLLECTION',1780157324259,false),
  ('30bb0e51-534c-8600-ecd0-587dbb105ce2','00000000-0000-0000-0000-000000000019','Bullwhip — 10-foot Plaited','Kangaroo hide, custom braided','Historical Artifacts','Tools',NULL,'Swings across chasms. Wraps around torch brackets. Essential.',45000,15000,true,'COLLECTION',1780160924259,false),
  ('ee0dcc67-2c89-be46-39f9-72f7ddd25c77','00000000-0000-0000-0000-000000000019','University Tenure Letter — Marshall College','Archaeology Department, 1936','Books & Manuscripts','Personal Papers',NULL,'He keeps forgetting to submit grades. Still has tenure.',4500,1500,true,'COLLECTION',1780164524259,false),
  ('ed1d86f6-6ba5-fd01-9a66-21d4011eaddb','00000000-0000-0000-0000-000000000019','Harrison Ford Honorary Degree','Fictional — from the college prop department','Books & Manuscripts','Personal Papers',NULL,'Walton is Walton. Not saying anything else.',2800,1000,true,'COLLECTION',1780168124259,false),
  ('98a55347-ad70-b286-fffc-029048c21710','00000000-0000-0000-0000-000000000019','Rosetta Stone Squeeze — Original Impression','Plaster squeeze of hieroglyphic panel','Antiquities','Egyptian',NULL,'Taken in the field. The British Museum has the original.',22000,8000,true,'COLLECTION',1780171724259,false),
  ('e95c4a76-3243-3895-1251-6b0a31ef5346','00000000-0000-0000-0000-000000000019','Canopic Jar — Hapy Baboon Lid','Egyptian faience, 18th Dynasty','Antiquities','Egyptian',NULL,'Contains preserved organs. Lungs, specifically. Do not open.',48000,17000,true,'COLLECTION',1780175324259,false),
  ('fa0adc12-1d4a-653e-8f82-9282b7fbbbdc','00000000-0000-0000-0000-000000000019','Scarab Pectoral — Lapis and Gold','New Kingdom, c. 1350–1200 BC','Antiquities','Egyptian',NULL,'Broad collar with winged scarab. Tomb excavation, Luxor.',380000,135000,true,'COLLECTION',1780178924259,false),
  ('f54ad399-b18c-27d1-7112-1c183ac23a26','00000000-0000-0000-0000-000000000019','Mummy','Ptolemaic mummification, c. 200 BC','Antiquities','Egyptian',NULL,'Detached during the Cairo incident. Not proud of it.',28000,10000,true,'COLLECTION',1780182524259,false),
  ('cd5816f8-3915-2c01-c09a-4dd7fc51898f','00000000-0000-0000-0000-000000000019','Greek Trireme Bronze Ram','Athens, c. 480 BC','Antiquities','Greek',NULL,'Recovered from the Salamis battle site. Underwater excavation.',680000,240000,true,'COLLECTION',1780186124259,false),
  ('9d1908c8-ea58-d370-db92-100a7126397e','00000000-0000-0000-0000-000000000019','Roman Gladius — Pompeii Type','Iron and bone, 1st Century AD','Antiquities','Roman',NULL,'From a soldier',95000,34000,true,'COLLECTION',1780189724259,false),
  ('bfaaf7e6-1be9-d813-9275-58102789dab0','00000000-0000-0000-0000-000000000019','Trojan Horse Schematic','Greek papyrus fragment, c. 500 BC','Books & Manuscripts','Manuscripts',NULL,'Engineering diagram. Whether Troy is real — debated. This isn',280000,98000,true,'COLLECTION',1780193324259,false),
  ('4d21edc7-baba-5e74-13c7-4970ebb85c96','00000000-0000-0000-0000-000000000019','Aztec Calendar Stone Rubbing','Life-size paper rubbing, Tenochtitlan','Books & Manuscripts','Manuscripts',NULL,'Not the end of the world. Just a calendar. People misread it.',22000,8000,true,'COLLECTION',1780196924259,false),
  ('d92de3e2-b46e-0158-e593-8235ff933091','00000000-0000-0000-0000-000000000019','Mayan Jade Mask — Death God','Jade mosaic, Palenque, c. 700 AD','Antiquities','Pre-Columbian',NULL,'Burial mask from a Palenque royal tomb.',1800000,640000,true,'COLLECTION',1780200524259,false),
  ('c047c613-4475-e33f-703b-21991f7cf854','00000000-0000-0000-0000-000000000019','Olmec Colossal Head — Miniature Cast','Basalt reproduction, 1:24 scale','Historical Artifacts','Models',NULL,'Largest heads weigh 40 tons. This one is manageable.',4500,1600,true,'COLLECTION',1780204124259,false),
  ('040bab83-0f52-613f-f552-348f3f9b44e8','00000000-0000-0000-0000-000000000019','Knight Templar Seal — Grand Master','Bronze, c. 1150','Antiquities','Medieval',NULL,'Templars guarded the Grail. Walton found this near Jerusalem.',180000,64000,true,'COLLECTION',1780207724259,false),
  ('194a09e2-fe20-45fa-7261-acb5f735b390','00000000-0000-0000-0000-000000000019','Arthurian Round Table Fragment','Oak, c. medieval, Winchester Castle type','Historical Artifacts','Medieval',NULL,'The Winchester table dates to 1290. This shard matches the grain.',85000,30000,true,'COLLECTION',1780211324259,false),
  ('be2bfadd-581b-a8cd-2e98-fbf2a836481a','00000000-0000-0000-0000-000000000019','Merlin','Gnarled wood, rune-carved','Historical Artifacts','Curiosities',NULL,'Acquired from a Welsh monastery. Monks were relieved to see it go.',480000,0,true,'COLLECTION',1780214924259,false),
  ('3d06aa30-5200-28b3-9550-fe14d218e691','00000000-0000-0000-0000-000000000019','Henry Walton Sr.','Leather-bound, father','Books & Manuscripts','Personal Papers',NULL,'Three hundred pages of Grail research. Postcards inside.',380000,0,true,'COLLECTION',1780218524259,false),
  ('8a888591-64fe-dbfa-4fa9-76236e14f1f0','00000000-0000-0000-0000-000000000019','Dead Sea Scroll Fragment','Qumran Cave 4, Isaiah text','Books & Manuscripts','Manuscripts',NULL,'Acquired through legitimate channels. The Israeli government disagrees.',2800000,0,true,'COLLECTION',1780222124259,false),
  ('030a5e54-5358-1490-1fae-d782f4c9fe66','00000000-0000-0000-0000-000000000019','Navigation Chart — 1513 Piri Reis Map','Facsimile of the Antarctic coastline map','Books & Manuscripts','Maps',NULL,'Depicts Antarctica before it was discovered. Source debated.',28000,10000,true,'COLLECTION',1780225724259,false),
  ('4d0274c8-1ac7-b102-9962-493ffb5f33cf','00000000-0000-0000-0000-000000000019','Shang Dynasty Oracle Bone','Inscribed ox scapula, c. 1200 BC','Antiquities','Chinese',NULL,'Divination record. Earliest Chinese writing.',280000,98000,true,'COLLECTION',1780229324259,false),
  ('aaa99fb7-63cc-740e-9bd9-513e37ea7766','00000000-0000-0000-0000-000000000019','Silk Road Caravanserai Token','Bronze, Sogdian, c. 700 AD','Coins & Currency','Ancient Coins',NULL,'Used at trading posts along the Silk Road.',8500,3000,true,'COLLECTION',1780232924259,false),
  ('3d06770b-f00c-4687-a2f1-f231b405a614','00000000-0000-0000-0000-000000000019','Japanese Katana — Muromachi Period','c. 1350–1573','Historical Artifacts','Arms & Militaria',NULL,'Signed blade. Perfect curvature. Active spirit. Be respectful.',380000,135000,true,'COLLECTION',1780236524259,false),
  ('f08a80ef-63e4-4ff5-08f5-0ce80cc7b237','00000000-0000-0000-0000-000000000019','Queen of Sheba','Gold with engraved seal, Ethiopian tradition','Antiquities','African',NULL,'Ethiopian tradition places the Ark in Axum. The ring points there.',1200000,0,true,'COLLECTION',1780240124259,false),
  ('779fdb90-00f6-19cd-1401-df08545ae6eb','00000000-0000-0000-0000-000000000019','Great Zimbabwe Bird — Soapstone','Zimbabwe, c. 1200–1400 AD','Antiquities','African',NULL,'One of eight birds. Symbol of the Great Zimbabwe civilization.',680000,240000,true,'COLLECTION',1780243724259,false),
  ('6b695f8d-ab3e-fc44-151c-c630813a700a','00000000-0000-0000-0000-000000000019','Compass — Brunton Professional','Brass, 1930s field model','Historical Artifacts','Scientific Instruments',NULL,'Used on every expedition since 1933. Still accurate.',4500,1600,true,'COLLECTION',1780247324259,false),
  ('c4b61e00-5ff1-ffa6-a065-17bea961af62','00000000-0000-0000-0000-000000000019','Colt 1917 Revolver','.45 ACP, field worn','Historical Artifacts','Arms & Militaria',NULL,'Standard issue. Reliable. Never as fast as the sword guy.',8500,3000,true,'COLLECTION',1780250924259,false),
  ('2391a0c5-e493-fe7b-8188-83767518843f','00000000-0000-0000-0000-000000000019','Snake — Preserved','Various species, formaldehyde','Natural History','Animal Specimens',NULL,'He hates snakes. Keeps them anyway. Academic interest only.',1200,450,true,'COLLECTION',1780254524259,false),
  ('23f79622-40fa-374a-d941-7b9ef9d99ba6','00000000-0000-0000-0000-000000000019','Dig Site Photograph Album','Black and white, 1930s–1950s','Books & Manuscripts','Photographs',NULL,'Every major dig documented. Colleagues, discoveries, close calls.',18000,6500,true,'COLLECTION',1780258124259,false),
  ('0b5dd3dc-4987-55d0-6048-b9dfb3eab67b','00000000-0000-0000-0000-000000000019','Viking Runestone — Portable','Limestone, 9th Century, Norse inscription','Antiquities','Viking',NULL,'Carried it from Sweden on his back. Worth it.',145000,52000,true,'COLLECTION',1780261724259,false),
  ('d55eff74-fe1d-98ac-835a-598177d8e986','00000000-0000-0000-0000-000000000019','El Dorado Gold Mask','Muisca culture, Colombia, c. 1000 AD','Antiquities','Pre-Columbian',NULL,'From the legend of the golden man. Genuine Muisca goldwork.',2400000,840000,true,'COLLECTION',1780265324259,false),
  ('2fbf8d8a-b403-949b-3af1-77c44a4a8f8f','00000000-0000-0000-0000-000000000019','Incan Quipu — Knotted Records','Colored string accounting device, c. 1450','Antiquities','Pre-Columbian',NULL,'Records a tribute payment. Some quipus contain narrative text.',85000,30000,true,'COLLECTION',1780268924259,false),
  ('e6ad9414-4556-3e92-12c1-71bfc6375150','00000000-0000-0000-0000-000000000019','Atlantean Orichalcum Fragment','Unknown metal alloy, pre-historic','Antiquities','Curiosities',NULL,'Plato described orichalcum. This matches no known alloy.',4800000,0,true,'COLLECTION',1780272524259,false),
  ('4d780b7d-fa64-1304-f6d0-67f647011b94','00000000-0000-0000-0000-000000000019','Marshall College Lecture Notes — Archaeology 101','Mimeograph, 1938 semester','Books & Manuscripts','Personal Papers',NULL,'Students love him. He is never actually there.',2800,1000,true,'COLLECTION',1780276124259,false)
INSERT INTO vault_items (id,profile_id,title,subtitle,universe,category,grade,notes,current_value,purchase_price,is_public,status,created_at,is_new) VALUES
  ('fd2cee56-6ffb-51c5-c604-08942f8f82fc','00000000-0000-0000-0000-000000000020','The Phantom','Porcelain and leather, c. 1880','Historical Artifacts','Costume & Dress',NULL,'Concealing the right side of the face. Never willingly removed.',1800000,0,true,'COLLECTION',1780135724259,false),
  ('c3e9793b-4aed-b123-f2fb-614afc42e5bc','00000000-0000-0000-0000-000000000020','Don Juan Triumphant — Autograph Score','Full opera manuscript, Erik','Books & Manuscripts','Music Manuscripts',NULL,'Composed over twenty years. Performed once. The night everything ended.',4800000,0,true,'COLLECTION',1780139324259,false),
  ('7c16ff82-f3cc-1c11-92a5-7acc15946398','00000000-0000-0000-0000-000000000020','Pipe Organ — Subterranean','Custom built beneath Paris, c. 1870','Music & Instruments','Organs',NULL,'127 pipes. Plays through the walls of the Opéra above.',2200000,0,true,'COLLECTION',1780142924259,false),
  ('362022ee-a536-c8a5-d216-08372df83deb','00000000-0000-0000-0000-000000000020','Christine','White roses, performance night','Historical Artifacts','Personal Effects',NULL,'From her debut performance. He watched from Box 5.',22000,0,true,'COLLECTION',1780146524259,false),
  ('42497d98-ab4b-3461-6458-1601cb33c239','00000000-0000-0000-0000-000000000020','Punjab Lasso — Silk and Lead','Execution weapon, c. 1880','Historical Artifacts','Arms & Militaria',NULL,'Erik learned this in Persia. Soundless. Effective.',85000,0,true,'COLLECTION',1780150124259,false),
  ('b8e07f62-24f8-3d78-e43c-588695f4cd33','00000000-0000-0000-0000-000000000020','Paris Opéra Chandelier Counterweight','Iron, Garnier opera house, 1875','Historical Artifacts','Architectural',NULL,'That night. The chandelier. The incident.',280000,0,true,'COLLECTION',1780153724259,false),
  ('5ec20c76-8b34-3b46-12ed-14ff0c74aeb9','00000000-0000-0000-0000-000000000020','Underground Lake Mirror','Venetian glass, sealed in moisture','Decorative Arts','Mirrors',NULL,'His reflection is the only one he could bear to face.',48000,0,true,'COLLECTION',1780157324259,false),
  ('96fd1d74-5064-b024-c91e-954dd863a9f7','00000000-0000-0000-0000-000000000020','Le Fantôme de l','Paris, 1910 — serialized then bound','Books & Manuscripts','Rare Books',NULL,'His story. He finds it mostly accurate. The nose detail is wrong.',45000,0,true,'COLLECTION',1780160924259,false),
  ('9a87db81-4565-dad6-5d53-4db55f78e37f','00000000-0000-0000-0000-000000000020','Raoul','Diamond solitaire, c. 1880','Jewelry & Accessories','Rings',NULL,'Christine eventually chose Raoul. The ring sat here after.',28000,0,true,'COLLECTION',1780164524259,false),
  ('48d656ca-1efe-9378-111d-300e774801b1','00000000-0000-0000-0000-000000000020','Box Five Reserved Card','Paris Opéra, standing reservation','Books & Manuscripts','Historical Documents',NULL,'Every performance. His box. Never to be sold.',8500,0,true,'COLLECTION',1780168124259,false),
  ('cfd6d8c3-0188-988e-956d-431227af976b','00000000-0000-0000-0000-000000000020','Persian Black Rope — Execution Style','Silk braided, c. 1880','Historical Artifacts','Arms & Militaria',NULL,'From his years in Persia. Before Paris.',22000,0,true,'COLLECTION',1780171724259,false),
  ('071a62ca-df91-5fea-96cd-c74d78e05ddc','00000000-0000-0000-0000-000000000020','Architecture Blueprint — Palais Garnier','Charles Garnier','Books & Manuscripts','Architectural Plans',NULL,'Erik helped build it. He knows every passage.',280000,85000,true,'COLLECTION',1780175324259,false),
  ('ad20366b-48cb-360b-2e47-3b17a81116da','00000000-0000-0000-0000-000000000020','Ventriloquist','Carved wood, dressed in evening clothes','Historical Artifacts','Curiosities',NULL,'Erik could throw his voice anywhere in the Opéra.',18000,0,true,'COLLECTION',1780178924259,false),
  ('52234101-ab5d-767c-0610-109af3f5713e','00000000-0000-0000-0000-000000000020','Music Box — Monkey Automaton','Persian craftsmanship, c. 1875','Science & Technology','Automata',NULL,'Plays Masquerade. The monkey',45000,0,true,'COLLECTION',1780182524259,false),
  ('1bf59734-869f-6d0f-3544-5276c57d9d24','00000000-0000-0000-0000-000000000020','Christine','Handwritten, Angel of Music notation','Books & Manuscripts','Music Manuscripts',NULL,'Breathing exercises in his hand. She thought she heard an angel.',85000,0,true,'COLLECTION',1780186124259,false),
  ('c6cd7681-1bc4-11aa-c72a-ab4654b01ca8','00000000-0000-0000-0000-000000000020','Death','Carved ebony, skull motifs','Decorative Arts','Furniture',NULL,'In the underground chamber. Where he composed.',95000,0,true,'COLLECTION',1780189724259,false),
  ('152a6709-6fbc-f378-af3f-642a46bdccc3','00000000-0000-0000-0000-000000000020','Persian Architecture Certificate','Award from the Shah, c. 1865','Books & Manuscripts','Historical Documents',NULL,'Erik designed palaces for the Shah before fleeing.',45000,0,true,'COLLECTION',1780193324259,false),
  ('278ad8ef-8a03-be13-4cce-401919b4044a','00000000-0000-0000-0000-000000000020','Trapdoor Mechanism Blueprint','Erik','Books & Manuscripts','Architectural Plans',NULL,'Twenty-three trapdoors in the Opéra. He designed seventeen.',65000,0,true,'COLLECTION',1780196924259,false),
  ('81813c93-b263-d29c-0987-ac3412733441','00000000-0000-0000-0000-000000000020','Carnival Mask — Red Death Style','Painted papier-mâché, c. 1880','Historical Artifacts','Costume & Dress',NULL,'The masquerade ball. His entrance. Their first real meeting.',22000,0,true,'COLLECTION',1780200524259,false),
  ('2507ef6b-ff7a-ec72-3f53-1e97449e97e1','00000000-0000-0000-0000-000000000020','Meyerbeer Opera Score — Annotated','Robert le Diable, heavily marked','Books & Manuscripts','Sheet Music',NULL,'Erik studied every major opera. His annotations are themselves art.',18000,6500,true,'COLLECTION',1780204124259,false),
  ('2a76e425-5273-72cc-7396-a1d36ad83312','00000000-0000-0000-0000-000000000020','Christine','Full-length, hinged on secret pivot','Historical Artifacts','Architectural',NULL,'The mirror that was also a door. To his world.',85000,0,true,'COLLECTION',1780207724259,false),
  ('519066c1-abdd-4728-6adb-e111529c9ab6','00000000-0000-0000-0000-000000000020','Candle Sconce — Underground Chamber','Iron, set into stone, c. 1870','Historical Artifacts','Lighting',NULL,'Hundreds of candles lit his underground home.',4500,0,true,'COLLECTION',1780211324259,false),
  ('7b47744e-b1bc-8ae0-53d3-0c4011003be9','00000000-0000-0000-0000-000000000020','Barrel Organ — Street Musician Style','Mechanical, c. 1860','Music & Instruments','Mechanical Music',NULL,'Erik',12000,4000,true,'COLLECTION',1780214924259,false),
  ('6e1db139-c805-9260-0fdc-1d10a8f56efe','00000000-0000-0000-0000-000000000020','Stradivarius Violin — Unplayed','c. 1715 — Cremona','Music & Instruments','Stringed Instruments',NULL,'He preferred keyboard. But kept this because it was perfect.',1800000,0,true,'COLLECTION',1780218524259,false),
  ('82b7a505-d24d-4bb7-deab-097b20c14899','00000000-0000-0000-0000-000000000020','Secret Passageway Map — Full Opera','Erik','Books & Manuscripts','Maps',NULL,'Every hidden corridor, secret door, and spy hole.',95000,0,true,'COLLECTION',1780222124259,false),
  ('fec897bb-8473-8d5a-6ec8-82142524301e','00000000-0000-0000-0000-000000000020','Faust Score — Gounod','First edition, Paris 1859','Books & Manuscripts','Sheet Music',NULL,'The opera running the night of the chandelier incident.',28000,9500,true,'COLLECTION',1780225724259,false),
  ('e8f4b364-59f6-7bae-7c04-a37f75384079','00000000-0000-0000-0000-000000000020','Gold Ring — Never Given','Plain band, intended for Christine','Jewelry & Accessories','Rings',NULL,'He had it made. She never knew.',18000,0,true,'COLLECTION',1780229324259,false),
  ('a4826f68-ed02-4186-bc86-65d0ffbb0cf7','00000000-0000-0000-0000-000000000020','Opera Ghost Letter — To Management','Handwritten, threatening tone','Books & Manuscripts','Personal Papers',NULL,'Demanding his salary of 20,000 francs per month.',22000,0,true,'COLLECTION',1780232924259,false),
  ('55cc09af-c8d8-c20f-a86c-07830e85871b','00000000-0000-0000-0000-000000000020','Magic Lasso Instruction Scroll','Persian text, translated by Erik','Books & Manuscripts','Manuscripts',NULL,'The technique for the Punjab lasso. His Persian years.',28000,0,true,'COLLECTION',1780236524259,false),
  ('4de5e5b5-bd96-80ed-f06e-a46a238c8b5b','00000000-0000-0000-0000-000000000020','Torture Chamber Switch — Iron Lever','Activated the rotating mirror room','Historical Artifacts','Architectural',NULL,'The heat, the mirrors, the jungle wallpaper. His darkest invention.',22000,0,true,'COLLECTION',1780240124259,false),
  ('2881f7a4-d4ae-6836-2cb5-8332b7779a11','00000000-0000-0000-0000-000000000020','Phantom of the Opera — Broadway Playbill','1988 opening night, Majestic Theatre','Film & Entertainment','Programs',NULL,'Andrew Lloyd Webber',1800,650,true,'COLLECTION',1780243724259,false),
  ('918477aa-c058-a338-f107-9ba7e74fe127','00000000-0000-0000-0000-000000000020','Lon Chaney Makeup Notes','Universal Studios, 1925','Film & Entertainment','Film Artifacts',NULL,'How Chaney created the Phantom',28000,9500,true,'COLLECTION',1780247324259,false),
  ('88428a1e-1755-e12c-66d1-476c0254631c','00000000-0000-0000-0000-000000000020','Piano Sheet — Point of No Return','Autograph manuscript, Erik','Books & Manuscripts','Music Manuscripts',NULL,'The most dangerous duet ever written.',280000,0,true,'COLLECTION',1780250924259,false),
  ('3cbd1659-3226-040c-9838-8fd79e7e1de7','00000000-0000-0000-0000-000000000020','Underground Lake Gondola','Scale model, carved wood, c. 1880','Decorative Arts','Models',NULL,'The lake beneath the Opéra. He poled it himself.',12000,0,true,'COLLECTION',1780254524259,false),
  ('d9b0d526-7f71-ed3c-b9da-8fcd9b85654f','00000000-0000-0000-0000-000000000020','Ballet Slipper — Meg Giry','Pink satin, signed','Historical Artifacts','Costume & Dress',NULL,'Madame Giry',4500,0,true,'COLLECTION',1780258124259,false),
  ('a23410e2-5ea7-0f32-a301-3919b73a4fab','00000000-0000-0000-0000-000000000020','Persian Iron Mask Fragment','Punishment device, c. 1865','Historical Artifacts','Arms & Militaria',NULL,'From the Shah',45000,0,true,'COLLECTION',1780261724259,false),
  ('58dfb855-1647-72b6-ab15-d807c12520f5','00000000-0000-0000-0000-000000000020','Composition Desk — Underground','Mahogany writing table, c. 1870','Decorative Arts','Furniture',NULL,'Where Don Juan Triumphant was written. Ink stains in the grain.',48000,0,true,'COLLECTION',1780265324259,false),
  ('e676c869-3cd0-77f6-07d2-21367cc633e7','00000000-0000-0000-0000-000000000020','Mirrored Ball — Masquerade','Crystal and silver, c. 1880','Decorative Arts','Decorative Objects',NULL,'From the Opéra',18000,6000,true,'COLLECTION',1780268924259,false),
  ('8e0259a7-ae72-8d69-511a-4fb5feb9aec1','00000000-0000-0000-0000-000000000020','Sheet Music Stand — Wrought Iron','Custom, c. 1875','Music & Instruments','Musical Accessories',NULL,'Holds the score steady. Used for every composition session.',4500,0,true,'COLLECTION',1780272524259,false),
  ('708be257-c2da-72f7-3c9e-5a548b852de1','00000000-0000-0000-0000-000000000020','The Angel of Music — Final Note','Last composition, 1881','Books & Manuscripts','Music Manuscripts',NULL,'Written the night Christine left. Twelve bars. Unfinished.',2800000,0,true,'COLLECTION',1780276124259,false)
INSERT INTO vault_items (id,profile_id,title,subtitle,universe,category,grade,notes,current_value,purchase_price,is_public,status,created_at,is_new) VALUES
  ('8f831856-697a-4f59-1322-398430b3febc','00000000-0000-0000-0000-000000000021','1928 National Style O Resonator Guitar','Steel body, Hawaiian lap steel tuning','Music & Instruments','Guitars',NULL,'The guitar. Played at the crossroads. Never needed tuning after that night.',485000,0,true,'COLLECTION',1780135724259,false),
  ('13c88966-5a7b-8ef7-df39-5298a87e64d9','00000000-0000-0000-0000-000000000021','Slide — Bottleneck Glass','Broken Midnight Special bottle, 1930','Music & Instruments','Guitar Accessories',NULL,'Cut from a whiskey bottle. The tone was never replicated.',28000,0,true,'COLLECTION',1780139324259,false),
  ('36ef9f4c-f757-3277-cacd-8dd7d252a113','00000000-0000-0000-0000-000000000021','1931 Gibson L-1 Flat-Top Guitar','The second guitar. For recording.','Music & Instruments','Guitars',NULL,'Used for the Grafton sessions. Spruce top, mahogany back.',185000,85000,true,'COLLECTION',1780142924259,false),
  ('23b1af1c-29ec-f2f3-4393-40c4fa10524a','00000000-0000-0000-0000-000000000021','Harmonica — Hohner Marine Band Key of A','c. 1928','Music & Instruments','Harmonicas',NULL,'Second instrument. Played simultaneously in the early juke joints.',8500,0,true,'COLLECTION',1780146524259,false),
  ('103e740d-f694-55d3-1df0-8895945a65cf','00000000-0000-0000-0000-000000000021','Crossroads Dirt — Dockery Plantation','Sealed glass vial, Mississippi clay','Historical Artifacts','Curiosities',NULL,'From the exact intersection. Collected midnight. Still warm.',22000,0,true,'COLLECTION',1780150124259,false),
  ('7ab83b1b-6f6c-a365-9cd8-c6f0b853d44f','00000000-0000-0000-0000-000000000021','Tuning Peg — Replaced at the Crossroads','Original machine head, steel','Historical Artifacts','Curiosities',NULL,'The old tuning peg. Replaced by a stranger at midnight.',45000,0,true,'COLLECTION',1780153724259,false),
  ('1bbe1f24-7335-55e9-ff67-11a40cc6eeef','00000000-0000-0000-0000-000000000021','Contract — Written in the Dirt','Photograph of ground markings, 1930','Books & Manuscripts','Photographs',NULL,'Farmhand photographed the markings at dawn. Still unexplained.',85000,0,true,'COLLECTION',1780157324259,false),
  ('23b9cbdf-ec12-dfaf-72cc-f2e342a7b54c','00000000-0000-0000-0000-000000000021','78 RPM Record — Cross Road Blues','Vocalion 03519, 1936','Music & Instruments','Vinyl Records',NULL,'Original pressing. Transferred from a single session in San Antonio.',95000,0,true,'COLLECTION',1780160924259,false),
  ('5b837545-487e-9a98-929e-3a7ea3e3900f','00000000-0000-0000-0000-000000000021','78 RPM — Hellhound on My Trail','Vocalion 03623, 1937','Music & Instruments','Vinyl Records',NULL,'The most haunted three minutes in American music.',95000,0,true,'COLLECTION',1780164524259,false),
  ('bb9c2314-030d-6459-8b7d-6ee076cf0508','00000000-0000-0000-0000-000000000021','Recording Session Receipt — Grafton Wisconsin','Paramount Records, 1929','Books & Manuscripts','Historical Documents',NULL,'Payment stub. $20 for two sides. The session that started everything.',22000,0,true,'COLLECTION',1780168124259,false),
  ('78f64801-8a0e-66ce-e033-dc7b6ebacb95','00000000-0000-0000-0000-000000000021','78 RPM — Love in Vain','Vocalion 04630, 1937','Music & Instruments','Vinyl Records',NULL,'Slow blues. Rolling Stones covered it. Nothing matched the original.',85000,0,true,'COLLECTION',1780171724259,false),
  ('f34ff125-7b0d-bf21-3001-7521ff774d18','00000000-0000-0000-0000-000000000021','78 RPM — Me and the Devil Blues','Vocalion 04108, 1937','Music & Instruments','Vinyl Records',NULL,NULL,85000,0,true,'COLLECTION',1780175324259,false),
  ('0a8693c4-d5a9-412e-5d08-c13238d6df54','00000000-0000-0000-0000-000000000021','Solomon King','Gelatin silver, c. 1935','Books & Manuscripts','Photographs',NULL,'One of two confirmed photographs. Coin-operated machine, dime store.',180000,0,true,'COLLECTION',1780178924259,false),
  ('b5282d6b-bffe-8d84-b5bc-ccbc6629ccca','00000000-0000-0000-0000-000000000021','Death Certificate — August 16, 1938','Leflore County, Mississippi','Books & Manuscripts','Historical Documents',NULL,'Cause: unknown. Age: 27. Some say poison. Some say something else.',45000,0,true,'COLLECTION',1780182524259,false),
  ('dab7c3ac-d51d-6263-f94c-a23b563439f1','00000000-0000-0000-0000-000000000021','Traveling Suit — Brown Wool','c. 1930s, Southern style','Historical Artifacts','Clothing',NULL,'Solomon dressed sharp. Always. Even in juke joints.',18000,0,true,'COLLECTION',1780186124259,false),
  ('a3513faa-b253-f3f2-7d1c-4c9f3b2f665d','00000000-0000-0000-0000-000000000021','Juke Joint Sign — Three Forks','Painted wood, c. 1930s','Historical Artifacts','Signs',NULL,'The Three Forks Store in Greenwood. Where he played his last show.',22000,8000,true,'COLLECTION',1780189724259,false),
  ('33c012d1-e8e2-3152-a02a-8c031e4a7d65','00000000-0000-0000-0000-000000000021','Dockery Plantation Work Card','Sunflower County, Mississippi, c. 1910','Books & Manuscripts','Historical Documents',NULL,'Dockery Plantation was where the Delta blues was born.',8500,3000,true,'COLLECTION',1780193324259,false),
  ('64877647-ea88-b8bd-c39a-96ef701faf71','00000000-0000-0000-0000-000000000021','Mississippi Delta Map — 1930','Hand-drawn county boundaries','Books & Manuscripts','Maps',NULL,'The birthplace. Every name on this map is a blues song.',12000,4500,true,'COLLECTION',1780196924259,false),
  ('1f68edb7-72a7-3c8a-e86c-d02a6a03acbb','00000000-0000-0000-0000-000000000021','Sharecropper','Sunflower County, 1920s','Books & Manuscripts','Historical Documents',NULL,'The system that kept Black farmers in debt forever. Context.',8500,3000,true,'COLLECTION',1780200524259,false),
  ('372baf85-7105-6354-c4e7-b35da71841d5','00000000-0000-0000-0000-000000000021','Jim Crow Railroad Car Notice','Illinois Central, c. 1920','Books & Manuscripts','Historical Documents',NULL,'Separate cars. Solomon rode them north to Chicago eventually.',4500,1600,true,'COLLECTION',1780204124259,false),
  ('9157aaa1-9046-3f7f-72eb-d5298ef5ec28','00000000-0000-0000-0000-000000000021','Chicago Defender Newspaper','January 1917 — calling Black Southerners north','Books & Manuscripts','Newspapers',NULL,'The paper that advertised the Great Migration. Solomon read it.',8500,3000,true,'COLLECTION',1780207724259,false),
  ('e5082ae8-076d-00ad-fab7-b0513aadcfc6','00000000-0000-0000-0000-000000000021','Illinois Central Train Ticket — Jackson to Chicago','c. 1930s','Historical Artifacts','Travel',NULL,'The route north. Blues musicians followed it to Chess Records.',4500,1600,true,'COLLECTION',1780211324259,false),
  ('5914829d-d5c3-8dbb-6272-a8d4c540e94c','00000000-0000-0000-0000-000000000021','Washboard — Rhythm Instrument','Zinc, c. 1920','Music & Instruments','Percussion',NULL,'Used in early jug band sessions. Pre-drum kit blues percussion.',4500,1600,true,'COLLECTION',1780214924259,false),
  ('ff95561e-85f3-3a45-8f19-53da8c9323b9','00000000-0000-0000-0000-000000000021','Jug — Moonshine Vessel / Instrument','Stoneware, c. 1920','Music & Instruments','Curiosities',NULL,'Blowing across the mouth creates bass tones. Jug bands.',4500,1600,true,'COLLECTION',1780218524259,false),
  ('2f8a4345-d830-c8e9-13cc-9f0e4b37783e','00000000-0000-0000-0000-000000000021','Sonny Boy Williamson','Hohner chromatic, c. 1935','Music & Instruments','Harmonicas',NULL,'Acquired through trade. Sonny Boy played Chicago blues.',22000,8000,true,'COLLECTION',1780222124259,false),
  ('84d8ff0d-5c1c-35ee-911b-ce9f30d1473c','00000000-0000-0000-0000-000000000021','Clarksdale Juke Joint Photograph','Silver gelatin print, c. 1935','Books & Manuscripts','Photographs',NULL,'Saturday night. Dancers visible. Music happening.',12000,4500,true,'COLLECTION',1780225724259,false),
  ('0b4bccfd-231d-31b1-c620-36049e1486fa','00000000-0000-0000-0000-000000000021','Blues Lyric Notebook','Composition book, pencil','Books & Manuscripts','Notebooks',NULL,'Draft lyrics. Some became recordings. Some are better left here.',95000,0,true,'COLLECTION',1780229324259,false),
  ('a16e988c-04a2-339a-1966-8f9474af1e5f','00000000-0000-0000-0000-000000000021','Eric Clapton Letter — On the Blues','Personal letter, 1968','Books & Manuscripts','Autographs',NULL,'Clapton credits the Delta masters as his foundation.',28000,10000,true,'COLLECTION',1780232924259,false),
  ('a93c0f6d-b5fe-f318-3287-59504b283e29','00000000-0000-0000-0000-000000000021','Rolling Stones — Love in Vain Single','Decca Records, 1969','Music & Instruments','Vinyl Records',NULL,'Their cover. Solomon wrote it in 1937.',4500,1600,true,'COLLECTION',1780236524259,false),
  ('e7a0276b-3972-15d3-ab59-b28fe7163b6d','00000000-0000-0000-0000-000000000021','Led Zeppelin Borrowed Melody Notice','Copyright filing, c. 1970','Books & Manuscripts','Legal Documents',NULL,'Whole Lotta Love owes something to Solomon',8500,3000,true,'COLLECTION',1780240124259,false),
  ('1512bfc6-7eab-dca3-5ff3-0001655f6b57','00000000-0000-0000-0000-000000000021','Black Cat Bone','Hoodoo folk object, Mississippi','Historical Artifacts','Folk Magic',NULL,'Lucky charm of the Delta. Carried by bluesman for protection.',4500,0,true,'COLLECTION',1780243724259,false),
  ('7e5e55a5-1311-f3cc-c406-5b9eddc7d403','00000000-0000-0000-0000-000000000021','High John the Conqueror Root','Jalap root, folk magic','Historical Artifacts','Folk Magic',NULL,'Conjure root. Protection against evil. Standard issue in 1930s Mississippi.',2800,0,true,'COLLECTION',1780247324259,false),
  ('0f88f7a7-c543-1570-bdd0-087cd4baecc8','00000000-0000-0000-0000-000000000021','Crossroads Sign — Highway 61 and 49','Replica of the Clarksdale intersection marker','Historical Artifacts','Signs',NULL,'The actual crossroads. Every blues pilgrimage ends here.',4500,1600,true,'COLLECTION',1780250924259,false),
  ('b18befac-0ff6-315f-eec6-e69b1bb988f4','00000000-0000-0000-0000-000000000021','Cigar Box Guitar — Homemade','Three-string, c. 1920','Music & Instruments','Guitars',NULL,'How it started. Before you could buy a guitar, you built one.',8500,0,true,'COLLECTION',1780254524259,false),
  ('bee7ad07-b3a4-faf5-e587-8fdf72873b37','00000000-0000-0000-0000-000000000021','Vocalion Record Label — Blanks','Unused record labels, 1930s','Historical Artifacts','Music Ephemera',NULL,'The label that pressed all the early blues sides.',4500,1600,true,'COLLECTION',1780258124259,false),
  ('ab09c2cd-d162-b2a4-7fe2-97f14e60cc40','00000000-0000-0000-0000-000000000021','W.C. Handy — Blues Publication','Memphis Blues sheet music, 1912','Books & Manuscripts','Sheet Music',NULL,'First published blues song. Before the Delta recordings.',8500,3000,true,'COLLECTION',1780261724259,false),
  ('d26fb9bc-0021-c0d0-82a6-ad90012d420a','00000000-0000-0000-0000-000000000021','Muddy Waters Chess Records Contract','1948 — Chicago blues era','Books & Manuscripts','Historical Documents',NULL,'The bridge from Delta to Chicago. Solomon came first.',22000,8000,true,'COLLECTION',1780265324259,false),
  ('09562cd0-c742-86f6-c97c-68695ce54e2d','00000000-0000-0000-0000-000000000021','Dust Bowl Photograph — Mississippi 1930s','Farm Security Administration','Books & Manuscripts','Photographs',NULL,'The world Solomon sang about. Poverty and heat and hope.',8500,3000,true,'COLLECTION',1780268924259,false),
  ('6def7d06-5177-6d71-b75e-f190d23a8087','00000000-0000-0000-0000-000000000021','Club Ebony Poster — Indianola Mississippi','c. 1935','Historical Artifacts','Posters',NULL,'B.B. King',4500,1600,true,'COLLECTION',1780272524259,false),
  ('b74fca55-a713-1d00-8dd9-33d91eb1d76f','00000000-0000-0000-0000-000000000021','Last Known Residence Deed','Greenwood, Mississippi, 1938','Books & Manuscripts','Historical Documents',NULL,'A rented room. He had $3.40 when he died. The music was worth more.',18000,0,true,'COLLECTION',1780276124259,false)
